  import React, { useEffect, useState } from "react";
  import { v4 as uuidv4 } from 'uuid';

  // Ayırdığımız tipleri ve bileşenleri import ediyoruz
  import { Question, Message, DomainStatus } from './types';
  import Header from './components/Header';
  import ChatPanel from './components/ChatPanel';
  import Sidebar from './components/Sidebar';

  const App: React.FC = () => {
    const [questions, setQuestions] = useState<Question[]>([]);
    const [currentQuestionId, setCurrentQuestionId] = useState<number | null>(null);
    const [messages, setMessages] = useState<Message[]>([]);
    const [domainStatuses, setDomainStatuses] = useState<DomainStatus[]>([]);
    const [overallScore, setOverallScore] = useState<number>(0);
    const [isLoading, setIsLoading] = useState<boolean>(true);
    const [editingMessageId, setEditingMessageId] = useState<string | null>(null);

    // State yönetimi ve API çağrı mantığı aynı kalıyor...
    useEffect(() => {
      fetch("http://localhost:3001/questions").then(res => {
          if (!res.ok) throw new Error(`Network response was not ok: ${res.statusText}`);
          return res.json();
      }).then(data => {
        if (!Array.isArray(data) || data.length === 0) throw new Error("Fetched data is not valid.");
        setQuestions(data);
        const firstQuestion = data[0];
        setCurrentQuestionId(firstQuestion.id);
        setMessages([{ id: uuidv4(), sender: 'AI', text: "Welcome!", type: 'question', question: firstQuestion }]);
        const initialDomains: DomainStatus[] = [...new Set(data.map(q => q.domain_name))].map(name => ({ name, status: name === firstQuestion.domain_name ? 'In Progress' : 'Pending', score: 0 }));
        setDomainStatuses(initialDomains);
      }).catch(err => {
        console.error("Error fetching questions:", err);
        setMessages([{ id: uuidv4(), sender: 'AI', text: "Backend'e bağlanılamadı.", type: 'error', question: undefined }]);
      }).finally(() => setIsLoading(false));
    }, []);

     const recalculateScores = (currentMessages: Message[]) => {
    const initialStatuses: DomainStatus[] = [...new Set(questions.map(q => q.domain_name))].map(name => ({
      name,
      status: 'Pending',
      score: 0,
    }));

    // Her domain için toplam skoru ve cevap sayısını tut
    const domainScores = new Map<string, { total: number, count: number }>();

    for (const msg of currentMessages) {
      if (msg.type === 'user_response' && msg.answeredQuestionId) {
        const question = questions.find(q => q.id === msg.answeredQuestionId);
        // İlgili feedback mesajını bul (artık db_answer_id ile eşleşiyor)
        const feedback = currentMessages.find(f => f.type === 'feedback' && f.db_answer_id && f.db_answer_id === msg.db_answer_id);
        
        if (question && feedback && apiResponse) { // apiResponse'u dışarıdan almamak lazım, bu kısmı düzeltelim
             // Bu fonksiyonun içinde apiResponse'a erişim yok. Bu mantığı doğrudan setDomainStatuses içine taşımak daha doğru.
             // Şimdilik konsepti anlatmak için bu şekilde bırakıyorum, asıl hesaplama setDomainStatuses içinde yapılacak.
        }
      }
    }
    // Bu fonksiyonu şimdilik kullanmıyoruz, çünkü skor güncellemesi anlık yapılıyor.
    // Ancak daha karmaşık senaryolar için bu yapı kullanılabilir.
  };
  
    
    // ✅ YENİ: Edit mesaj fonksiyonu
    const handleEditMessage = async (messageId: string, newText: string) => {
      const messageIndex = messages.findIndex(m => m.id === messageId);
      if (messageIndex === -1) return;

      const originalMessage = messages[messageIndex];
      const questionId = originalMessage.answeredQuestionId;
      if (!questionId) return;

      setIsLoading(true);
      setEditingMessageId(null);

      try {
          const res = await fetch("http://localhost:3001/ask", {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({ prompt: newText, previous_question_id: questionId }),
          });
          if (!res.ok) throw new Error(`API error: ${res.statusText}`);
          const apiResponse = await res.json();

          // Mesajları güncelle
          setMessages(prevMessages => {
              const newMessages = [...prevMessages];
              // 1. Düzenlenen mesajın metnini güncelle
              newMessages[messageIndex] = { ...newMessages[messageIndex], text: newText };
              
              // 2. Bu cevaptan sonraki feedback mesajını bul ve güncelle
              const feedbackIndex = messageIndex + 1;
              if (newMessages[feedbackIndex]?.type === 'feedback') {
                  newMessages[feedbackIndex] = {
                      ...newMessages[feedbackIndex],
                      ai_comment: apiResponse.comment,
                      ai_task: apiResponse.task
                  };
              }
              return newMessages;
          });

          // Skorları da güncelle
          const answeredQuestion = questions.find(q => q.id === questionId);
          if (answeredQuestion) {
              setDomainStatuses(prevStatuses => {
                  const newStatuses = prevStatuses.map(status => {
                      if (status.name === answeredQuestion.domain_name) {
                          const domainQuestions = questions.filter(q => q.domain_name === status.name);
                          const questionWeight = 100 / (domainQuestions.length || 1);
                          const newScore = Math.min(100, (apiResponse.score / 100) * questionWeight);
                          return { ...status, score: newScore };
                      }
                      return status;
                  });
                  
                  const totalScore = newStatuses.reduce((acc, curr) => acc + curr.score, 0);
                  setOverallScore(totalScore / (newStatuses.length || 1));
                  return newStatuses;
              });
          }

      } catch (err) {
          console.error("Error editing message:", err);
      } finally {
          setIsLoading(false);
      }
    };


  const handlePreviousQuestion = () => {
    // Reverse ile tersine çevir ve ilk user_response'u bul
    const reversedMessages = [...messages].reverse();
    const lastUserResponse = reversedMessages.find((m: Message) => m.type === 'user_response');
    
    if (!lastUserResponse) return;
    
    const lastUserResponseIndex = messages.findIndex((m: Message) => m.id === lastUserResponse.id);
    
    // Bir önceki soruyu bul
    const previousQuestionMessage = messages
      .slice(0, lastUserResponseIndex)
      .reverse()
      .find((m: Message) => m.type === 'question');

    if (!previousQuestionMessage || !previousQuestionMessage.question) return;

    // State'i bir önceki duruma geri sar
    setMessages(prev => prev.slice(0, lastUserResponseIndex));
    setCurrentQuestionId(previousQuestionMessage.question.id);
  };


    const handleSendMessage = async (prompt: string) => {
      if (!currentQuestionId || isLoading) return;
      setIsLoading(true);

      // ✅ GÜNCELLENDİ: answeredQuestionId eklendi
      const userMessage: Message = { 
        id: uuidv4(), 
        sender: 'User', 
        text: prompt, 
        type: 'user_response',
        answeredQuestionId: currentQuestionId 
      };
      setMessages(prev => [...prev, userMessage]);

      try {
        const res = await fetch("http://localhost:3001/ask", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ prompt, previous_question_id: currentQuestionId }) });
        if (!res.ok) throw new Error(`API error: ${res.statusText}`);
        const apiResponse = await res.json();
        
        const feedbackMessage: Message = {
            id: uuidv4(),
            sender: 'AI',
            text: 'Feedback for your answer.',
            type: 'feedback',
            ai_comment: apiResponse.comment,
            ai_task: apiResponse.task,
        };
        
        const answeredQuestion = questions.find(q => q.id === currentQuestionId);
        const nextQuestion = questions.find(q => q.id === apiResponse.next_question_id);

        if (answeredQuestion) {
            setDomainStatuses(prevStatuses => {
                const newStatuses = prevStatuses.map(status => {
                    let updatedStatus = { ...status };
                    if (status.name === answeredQuestion.domain_name) {
                        const domainQuestions = questions.filter(q => q.domain_name === status.name);
                        const questionWeight = 100 / (domainQuestions.length || 1);
                        const newScore = Math.min(100, status.score + (apiResponse.score / 100) * questionWeight);
                        updatedStatus.score = newScore;
                        if (!nextQuestion || nextQuestion.domain_name !== status.name) updatedStatus.status = 'Complete';
                    }
                    if (nextQuestion && status.name === nextQuestion.domain_name && status.status === 'Pending') {
                        updatedStatus.status = 'In Progress';
                    }
                    return updatedStatus;
                });
                const totalScore = newStatuses.reduce((acc, curr) => acc + curr.score, 0);
                setOverallScore(totalScore / (newStatuses.length || 1));
                return newStatuses;
            });
        }
        
        const newMessages: Message[] = [feedbackMessage];
        if (nextQuestion) {
          newMessages.push({ id: uuidv4(), sender: 'AI', text: 'Here is the next question.', type: 'question', question: nextQuestion });
          setCurrentQuestionId(apiResponse.next_question_id);
        } else {
          newMessages.push({ id: uuidv4(), sender: 'AI', text: '🎉 Assessment complete!', type: 'question', question: undefined });
          setCurrentQuestionId(null);
        }
        setMessages(prev => [...prev, ...newMessages]);

      } catch (err) {
        console.error("Error sending message:", err);
        setMessages(prev => [...prev, { id: uuidv4(), sender: 'AI', text: "An error occurred.", type: 'error', question: undefined }]);
      } finally {
        setIsLoading(false);
      }
    };

    return (
      <div className="bg-[#0f0f23] text-gray-200 font-sans h-screen flex flex-col">
        <Header canGoBack={false} />
        <div className="flex flex-1 overflow-hidden">
          <ChatPanel 
            messages={messages} 
            onSendMessage={handleSendMessage} 
            isLoading={isLoading} 
            currentQuestionId={currentQuestionId}
            editingMessageId={editingMessageId}
            setEditingMessageId={setEditingMessageId}
            onEditMessage={handleEditMessage}
          />
          <Sidebar statuses={domainStatuses} overallScore={overallScore} />
        </div>
      </div>
    );
  };

  export default App;
